r"""
Crescopus - branded confirmation boxes

  - Replaces the browser's grey "OK / Cancel" pop-ups with a Crescopus box:
    brand fonts and colours, a clear title, an explanation of what will
    happen, and buttons that say what they do. On phones it slides up from
    the bottom with full-width buttons.
  - Rewritten messages for: withdrawing a dispute, deleting a ledger entry,
    deleting an app card, and marking a cost as Goodwill.
  - Permanent deletes use a red button.

HOW TO USE
  1. Run apply_crescoguide.py first if you haven't already (this builds on it).
  2. Save this file in your Crescopus project folder (next to wsgi.py).
  3. In PowerShell, in that folder, with your venv active:
         python apply_confirm_boxes.py
  4. No SQL to run.
  5. Any file it replaces is copied first to _backup_apply_confirm_boxes\.

It checks each file matches the version it expects first. If not, it stops
without writing anything.
Your .env is never read or changed.
"""
import base64, hashlib, os, shutil, sys

# (path, new content, sha256s of the versions it may replace)
FILES = [
    ('app/static/css/cresco-ui.css', '', ['57e147be500611a23c95e6353ec60b6366a045ceb8d422d0c8ed9f1ab971f6e5']),
    ('app/templates/base.html', '', ['5aa89fc1862b3c6f1c88c9ff1d7a6a2165eeaf5e0e6c2e6fe27c475f4296190b']),
    ('app/templates/browse/withdraw.html', '', ['d6c90efe00b5a604b7860c652c6c2568bde23e446e9f0db0d7e6c3bc22c72e34']),
    ('app/templates/ledger/dispute_view.html', '', ['4abb331284592f8f146e7adf99797d45e7889db323b13e4435391a597ba27774']),
    ('app/templates/ledger/entry_form.html', '', ['2e7051e0cf9f050e21e343393c2f2bd4975a784b3dfa7bd7e673cca02d92fd1d']),
    ('app/templates/ledger/view.html', '', ['10e14949cf880bc69944c7afff4d0729bed6d5e0c6a2b7352e6a3b4c79ba2aee']),
]
BACKUP = "_backup_apply_confirm_boxes"
NEXT = "restart python wsgi.py, try withdrawing a dispute (press Keep it open to cancel), then commit and push."

def sha(data):
    return hashlib.sha256(data).hexdigest()

def main():
    root = os.path.dirname(os.path.abspath(__file__))
    if not os.path.isfile(os.path.join(root, "app", "__init__.py")) or not os.path.isfile(os.path.join(root, "wsgi.py")):
        sys.exit("Stopped: put this file in the Crescopus project folder (next to wsgi.py and the app folder), then run it again.")

    # Safety check first: never overwrite local changes we don't know about.
    clashes = []
    for rel, b64, expected in FILES:
        path = os.path.join(root, *rel.split("/"))
        new = base64.b64decode(b64)
        if not os.path.exists(path):
            if expected:
                clashes.append(rel + " (missing)")
            continue
        with open(path, "rb") as fh:
            current = fh.read()
        current_norm = current.replace(b"\r\n", b"\n")
        if current == new or current_norm == new:
            continue
        if not expected or sha(current_norm) not in expected:
            clashes.append(rel)
    if clashes:
        print("Stopped - nothing written. These files differ from the version this update was built from:")
        for c in clashes:
            print("   " + c)
        sys.exit("If you haven't run apply_crescoguide.py yet, run it first and then run this again. Otherwise, push your latest changes and ask for the update to be rebuilt.")

    backup = os.path.join(root, BACKUP)
    changed = 0
    for rel, b64, expected in FILES:
        path = os.path.join(root, *rel.split("/"))
        data = base64.b64decode(b64)
        status = "new     "
        if os.path.exists(path):
            with open(path, "rb") as fh:
                current = fh.read()
            if current == data or current.replace(b"\r\n", b"\n") == data:
                print("same     " + rel)
                continue
            dest = os.path.join(backup, *rel.split("/"))
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            shutil.copy2(path, dest)
            status = "updated "
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as fh:
            fh.write(data)
        changed += 1
        print(status + " " + rel)
    print("\nDone - %d of %d files written." % (changed, len(FILES)))
    if os.path.isdir(backup):
        print("Originals of replaced files are in " + BACKUP + os.sep)
    if NEXT:
        print("Next: " + NEXT)

if __name__ == "__main__":
    main()
